<script setup lang="ts">
import {DialogRoot,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogDescription,DialogClose} from 'reka-ui'
import {emptyTranslation,type Draft,type Entry,type Branch,type Locale} from '~/shared/content'
useSeoMeta({title:'内容工作室 — KaimaFind',robots:'noindex, nofollow'})
const {data,error,refresh}=await useFetch('/api/admin/state')
const draft=ref<Draft|null>(null);const version=ref(0);const locale=ref<Locale>('zh');const message=ref('');const busy=ref(false);const dirty=ref(false);const preview=ref(false);const trash=ref(false);const tab=ref('content');const branchDraft=ref<Branch[]>([])
const entries=computed(()=>data.value?.entries.filter(e=>trash.value?!!e.deletedAt:!e.deletedAt)||[])
const current=computed(()=>data.value?.entries.find(e=>e.id===draft.value?.id))
const mapItems=computed(()=>data.value?.entries.filter(e=>!e.deletedAt).map(e=>{const {translations,...rest}=e.draft;return {...rest,translation:translations.zh,publishedAt:''}})||[])
function selectMap(id:string){const entry=data.value?.entries.find(e=>e.id===id);if(entry){select(entry);tab.value='content'}}
async function toggleFeature(id:string){if(dirty.value){message.value='请先保存当前内容';return}const entry=data.value?.entries.find(e=>e.id===id);if(!entry)return;busy.value=true;try{await $fetch('/api/admin/entry',{method:'POST',body:{draft:{...entry.draft,featured:!entry.draft.featured},version:entry.version}});await refresh();message.value='导览标记已存为草稿，进入内容发布后对外生效。'}catch(e){fail(e)}finally{busy.value=false}}
let timer:ReturnType<typeof setTimeout>|undefined;let suppress=false
function select(entry:Entry){if(dirty.value){message.value='当前内容尚未保存，请先保存后再切换。';return}clearTimeout(timer);suppress=true;draft.value=structuredClone(toRaw(entry.draft));version.value=entry.version;message.value='';nextTick(()=>{suppress=false;dirty.value=false})}
function create(kind:Draft['kind']){if(dirty.value){message.value='请先保存当前内容。';return}suppress=true;draft.value={id:crypto.randomUUID(),kind,branchId:data.value?.branches[0]?.id||'',relatedBranches:[],projectId:null,date:new Date().toISOString().slice(0,10),endDate:'',status:'ongoing',cover:'',media:[],featured:false,order:data.value?.entries.length||0,achievement:false,deliverable:false,translations:{zh:emptyTranslation(),en:emptyTranslation()}};version.value=0;nextTick(()=>{suppress=false;dirty.value=true})}
watch(draft,()=>{if(suppress||!draft.value)return;dirty.value=true;clearTimeout(timer);timer=setTimeout(()=>save(),1600)},{deep:true})
function fail(e:any){message.value=e?.data?.statusMessage||e?.message||'操作失败，请重试。';return false}
async function save(){if(!draft.value||busy.value)return false;clearTimeout(timer);busy.value=true;const snapshot=JSON.stringify(draft.value);try{const result=await $fetch('/api/admin/entry',{method:'POST',body:{draft:draft.value,version:version.value}});version.value=result.version;dirty.value=JSON.stringify(draft.value)!==snapshot;message.value=dirty.value?'还有修改待保存':'草稿已保存';await refresh();if(dirty.value)timer=setTimeout(()=>save(),1600);return true}catch(e){return fail(e)}finally{busy.value=false}}
async function action(action:'publish'|'unpublish'|'delete'|'restore'){if(!draft.value||busy.value)return;if(dirty.value && !(await save()))return;busy.value=true;try{const result=await $fetch('/api/admin/action',{method:'POST',body:{id:draft.value.id,version:version.value,action,locale:locale.value}});version.value=result.version;await refresh();message.value=({publish:'当前语言已发布',unpublish:'当前语言已撤回',delete:'已移入回收站',restore:'已恢复为草稿'})[action];if(action==='delete'||action==='restore'){draft.value=null;dirty.value=false}}catch(e){fail(e)}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||!draft.value)return;const body=new FormData();body.append('file',file);message.value='正在上传…';try{const media=await $fetch('/api/admin/upload',{method:'POST',body});const url=String(media.url||'');draft.value.media.push(url);if(String(media.type||'').startsWith('image/')){if(!draft.value.cover)draft.value.cover=url;else draft.value.translations[locale.value].body.content.push({type:'image',attrs:{src:url,alt:file.name}})}message.value='上传成功，正在保存草稿'}catch(e){fail(e)}input.value=''}
function addBranch(){branchDraft.value.push({id:crypto.randomUUID(),name:{zh:'新主线',en:''},parentId:null,order:branchDraft.value.length})}
async function editBranches(){tab.value='branches';branchDraft.value=structuredClone(toRaw(data.value?.branches||[]))}
async function saveBranches(){busy.value=true;try{await $fetch('/api/admin/branches',{method:'PUT',body:{branches:branchDraft.value,revision:data.value?.revision}});await refresh();message.value='主线已保存'}catch(e){fail(e)}finally{busy.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
async function logout(){if(dirty.value){message.value='请先保存当前内容';return}await $fetch('/api/logout',{method:'POST'});await navigateTo('/login')}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onBeforeUnmount(()=>{clearTimeout(timer);window.removeEventListener('beforeunload',beforeUnload)})
onBeforeRouteLeave(()=>{if(dirty.value){message.value='请先保存草稿后再离开。';return false}})
</script>
<template><div class="studio"><header class="studio-header"><NuxtLink to="/zh" class="wordmark">K.</NuxtLink><span>内容工作室</span><div><a href="/api/admin/export" class="text-link">导出内容</a><NuxtLink to="/zh" target="_blank">查看网站 ↗</NuxtLink><button @click="logout">退出</button></div></header>
 <main id="main"><div v-if="error" class="empty-state"><h1>后台尚未连接</h1><p>{{error.statusMessage||'请通过管理员登录入口访问。'}}</p><p>请重新登录后刷新页面。</p><NuxtLink to="/login">前往登录</NuxtLink><button @click="refresh()">重试</button></div>
 <template v-else-if="data"><div v-if="data.user.local" class="local-notice">本地开发工作室 · 内容保存在本机，不会发布到 kaimafind.com</div><div class="studio-layout"><aside class="studio-sidebar"><div class="studio-tabs"><button :class="{selected:tab==='content'}" @click="tab='content'">内容</button><button :class="{selected:tab==='map'}" @click="tab='map'">地图</button><button :class="{selected:tab==='branches'}" @click="editBranches">主线</button></div><div class="new-actions"><button @click="create('project');tab='content'">＋ 项目</button><button @click="create('progress');tab='content'">＋ 进展</button><button @click="create('work');tab='content'">＋ 作品</button></div><label class="check"><input type="checkbox" v-model="trash"> 回收站</label><button v-for="entry in entries" :key="entry.id" class="entry-row" :class="{selected:draft?.id===entry.id}" @click="select(entry);tab='content'"><span>{{entry.draft.translations.zh.title||entry.draft.translations.en.title||'未命名内容'}}</span><small>{{entry.draft.date}} / {{Object.keys(entry.published).length?'已发布':'草稿'}}{{entry.draft.featured?' / 精选':''}}</small></button><p v-if="!entries.length" class="muted">还没有内容。从一个项目开始。</p></aside>
 <section class="studio-editor"><p v-if="message" class="save-status" role="status">{{message}}</p>
 <template v-if="tab==='map'"><h1>在地图上编排</h1><p class="muted">点击项目进入编辑；点星标加入导览，再发布对应内容。</p><ClientOnly><LifeCanvas v-if="mapItems.length" :items="mapItems" :branches="data.branches" locale="zh" editing @select="selectMap" @feature="toggleFeature"/></ClientOnly><p v-if="!mapItems.length" class="empty-state">先创建一个项目，主线就会开始生长。</p></template><template v-else-if="tab==='branches'"><h1>人生主线</h1><p>主线可以持续增加；移动内容后才能删除原分支。</p><div v-for="b in branchDraft" :key="b.id" class="branch-editor"><label>中文名称<input v-model="b.name.zh"></label><label>英文名称<input v-model="b.name.en"></label><label>父分支<select v-model="b.parentId"><option :value="null">独立主线</option><option v-for="parent in branchDraft.filter(p=>p.id!==b.id)" :key="parent.id" :value="parent.id">{{parent.name.zh}}</option></select></label><label>排序<input type="number" v-model.number="b.order"></label><button @click="branchDraft=branchDraft.filter(p=>p.id!==b.id)">移除</button></div><button @click="addBranch()">＋ 添加主线</button><button class="solid-button" @click="saveBranches" :disabled="busy">保存主线</button></template>
 <template v-else-if="draft"><div class="editor-heading"><h1>{{({project:'项目',progress:'进展',work:'作品'})[draft.kind]}}</h1><div class="editor-actions"><button @click="preview=true">预览</button><button @click="save" :disabled="busy">{{busy?'处理中…':'保存草稿'}}</button><button class="solid-button" @click="action('publish')" :disabled="busy||!!current?.deletedAt">发布{{locale==='zh'?'中文':'英文'}}</button></div></div>
 <div class="language-tabs"><button :class="{selected:locale==='zh'}" @click="locale='zh'">中文 {{current?.published.zh?'•':''}}</button><button :class="{selected:locale==='en'}" @click="locale='en'">English {{current?.published.en?'•':''}}</button></div>
 <label class="field">标题<input v-model="draft.translations[locale].title" placeholder="给这段探索起个名字" maxlength="200"></label><label class="field">简介<textarea v-model="draft.translations[locale].summary" rows="2" maxlength="600" placeholder="用一两句话，说清楚这是什么。" /></label>
 <div class="field-row"><label>所属主线<select v-model="draft.branchId"><option v-for="b in data.branches" :key="b.id" :value="b.id">{{b.name.zh}}</option></select></label><label>发生时间<input v-model="draft.date" placeholder="2026 / 2026-11 / 2026-11-04"></label><label>状态<select v-model="draft.status"><option value="planned">筹备中</option><option value="ongoing">进行中</option><option value="completed">已完成</option><option value="paused">暂时搁置</option></select></label></div>
 <label v-if="draft.kind!=='project'" class="field">所属项目<select v-model="draft.projectId"><option :value="null">独立记录</option><option v-for="e in data.entries.filter(e=>e.draft.kind==='project'&&!e.deletedAt&&e.id!==draft?.id)" :key="e.id" :value="e.id">{{e.draft.translations.zh.title||'未命名项目'}}</option></select></label>
 <details class="relations"><summary>关联其他主线</summary><label v-for="b in data.branches.filter(b=>b.id!==draft?.branchId)" :key="b.id" class="check"><input type="checkbox" :value="b.id" v-model="draft.relatedBranches">{{b.name.zh}}</label></details>
 <ClientOnly><RichEditor v-model="draft.translations[locale].body" :key="draft.id+locale" /></ClientOnly>
 <div class="upload-area"><label class="upload-label">＋ 上传图片或 PDF<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" @change="upload"></label><p>图片 ≤10 MB · PDF ≤25 MB · 第一张图片自动设为封面</p></div><div class="media-grid"><div v-for="url in draft.media" :key="url"><img v-if="data.media.find(m=>'/media/'+m.id===url)?.type.startsWith('image/')" :src="url" alt="上传的作品"><a v-else :href="url" target="_blank">PDF 附件 ↗</a><button v-if="data.media.find(m=>'/media/'+m.id===url)?.type.startsWith('image/')" @click="draft.cover=url">{{draft.cover===url?'✓ 当前封面':'设为封面'}}</button><button @click="draft.media=draft.media.filter(m=>m!==url);if(draft.cover===url)draft.cover=''">移除附件引用</button></div></div>
 <div class="curation"><label class="check"><input type="checkbox" v-model="draft.featured">加入作品导览</label><label>导览顺序<input type="number" v-model.number="draft.order"></label><label class="check"><input type="checkbox" v-model="draft.achievement">阶段成就</label><label class="check"><input type="checkbox" v-model="draft.deliverable">可交付样品</label></div><p class="muted">导览和标记的修改在点击发布后对访客生效。中文与英文独立发布。</p>
 <div class="danger-actions"><button v-if="current?.published[locale]" @click="action('unpublish')" :disabled="busy">撤回当前语言</button><button v-if="current&&!current.deletedAt" @click="action('delete')" :disabled="busy">移入回收站</button><button v-if="current?.deletedAt" @click="action('restore')">恢复草稿</button></div>
 </template><div v-else class="studio-empty"><span class="studio-monogram">K.</span><h1>从一个真实的片段开始。</h1><p>创建项目，记录进展，或上传作品。<br>主线可以慢慢生长。</p><button class="solid-button" @click="create('project')">创建第一个项目</button></div>
 </section></div></template></main>
 <DialogRoot v-model:open="preview"><DialogPortal><DialogOverlay class="dialog-overlay"/><DialogContent class="preview-dialog"><DialogTitle>内容预览</DialogTitle><DialogDescription>仅供你预览。尚未发布的修改不会出现在公开页面。</DialogDescription><DialogClose class="dialog-close" aria-label="关闭预览">×</DialogClose><article v-if="draft" class="reading-column"><h1>{{draft.translations[locale].title}}</h1><p>{{draft.translations[locale].summary}}</p><img v-if="draft.cover" :src="draft.cover" alt="封面"><BodyNode :node="draft.translations[locale].body"/></article></DialogContent></DialogPortal></DialogRoot>
 </div></template>
